if(['Стикер','Стикерпак'].includes(category))return `<svg aria-hidden="true" width="45" height="45" viewBox="0 0 120 120"><rect x="22" y="15" width="77" height="87" rx="9" fill="white"/><rect x="29" y="22" width="63" height="73" rx="5" fill="currentColor" opacity=".16"/><path d="m45 34 5 12 14-4-5 13 8 10-14 1-6 13-6-12-14-2 10-10-2-14 11 6Z" fill="currentColor"/><circle cx="77" cy="73" r="15" fill="currentColor"/><path d="m70 72 5 5 8-9" fill="none" stroke="white" stroke-width="3" stroke-linecap="round"/><path d="M76 103h14a9 9 0 0 0 9-9V80Z" fill="white"/><path d="M76 103V87a7 7 0 0 1 7-7h16" fill="none" stroke="currentColor" opacity=".25"/></svg>`;
