function liveNumber(el){if(!el.dataset.change||el.value===''||!el.checkValidity())return false;const value=Number(el.value);if(!Number.isFinite(value))return false;switch(el.dataset.change){case'stock-qty':setPlanQuantity(state,el.dataset.id,value);updateStockSelection();break;case'profit':state.draft.profit=value;break;case'table':state.draft.table=value;break;case'round':state.draft.round=value;break;case'expense':state.draft.expenses.find(x=>x.id===el.dataset.id).amount=value;break;case'line-qty':state.draft.lines.find(x=>x.itemId===el.dataset.id).qty=value;break;case'line-price':state.draft.lines.find(x=>x.itemId===el.dataset.id).price=value;break;case'line-cost':state.draft.lines.find(x=>x.itemId===el.dataset.id).cost=value;break;case'promo-count':state.draft.promos.find(x=>x.id===el.dataset.id).count=value;break;default:return false;}return true;}
document.addEventListener('input',e=>{if(busy||storageReadOnly)return;const el=e.target;if(liveNumber(el)){persistDraft();scheduleNumbers();}if(el.id==='inventory-search'){search=el.value;const list=sortedInventory(state.inventory,{search,category:categoryFilter,sort:inventorySort});document.querySelector('#inventory-grid').innerHTML=list.map(inventoryCard).join('')||'<p class="small muted">Ничего не найдено.</p>';hydratePhotos();}if(el.dataset.live==='percent'){state.draft.sellPercent=Number(el.value);el.style.setProperty('--range-pct',el.value+'%');persistDraft();scheduleNumbers();}if(el.dataset.live==='promo'){state.draft.promos.find(p=>p.id===el.dataset.id).count=Number(el.value);el.style.setProperty('--range-pct',(Number(el.max)?Number(el.value)/Number(el.max)*100:0)+'%');el.closest('.promo-card').querySelector('[data-change=promo-count]').value=el.value;persistDraft();scheduleNumbers();}if(el.dataset.live==='price'){const line=state.draft.lines.find(l=>l.itemId===el.dataset.id);line.price=Number(el.value);el.style.setProperty('--range-pct',Number(el.value)/Number(el.max)*100+'%');const numberInput=el.closest('.manual-price-card').querySelector('[data-change=line-price]');if(numberInput)numberInput.value=el.value;persistDraft();scheduleNumbers();}});
document.addEventListener('change',e=>{if(busy)return;const el=e.target;if(el.id==='category-filter'){categoryFilter=el.value;render();return;}if(el.id==='report-month'){reportMonth=el.value||today().slice(0,7);shelfDetail(el.dataset.id);return;}if(['percent','promo'].includes(el.dataset.live)){const p=projection(state.draft);persistDraft();updateNumbers();return;}const kind=el.dataset.change;if(!kind)return;const value=Number(el.value);if(!el.checkValidity()||!Number.isFinite(value)){el.reportValidity();render();return;}switch(kind){case'stock-qty':setPlanQuantity(state,el.dataset.id,value);updateStockSelection();break;case'profit':state.draft.profit=value;break;case'table':state.draft.table=value;break;case'round':state.draft.round=value;break;case'expense':state.draft.expenses.find(x=>x.id===el.dataset.id).amount=value;break;case'line-qty':state.draft.lines.find(l=>l.itemId===el.dataset.id).qty=value;break;case'line-price':state.draft.lines.find(l=>l.itemId===el.dataset.id).price=value;break;case'line-cost':state.draft.lines.find(l=>l.itemId===el.dataset.id).cost=value;break;case'promo-count':state.draft.promos.find(p=>p.id===el.dataset.id).count=value;break;}const p=projection(state.draft);persistDraft();updateNumbers();});
sheet.addEventListener('click',e=>{if(e.target===sheet){const rect=sheet.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)closeSheet();}});

function flushState(){clearTimeout(saveTimer);if(state&&!isDemo&&!storageReadOnly){try{localStorage.setItem('solyanka-state-v1',JSON.stringify(state));}catch{}saveState(state).catch(()=>{});}}
window.addEventListener('pagehide',flushState);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')flushState();});
matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>{if(state)applyTheme();});
function initTelegram(){
 const tg=globalThis.Telegram?.WebApp;if(!tg?.initData)return;
 try{
  tg.ready();tg.expand();
  tg.onEvent('themeChanged',()=>{if(state)applyTheme();});
  const updateSafe=()=>{
   const system=tg.safeAreaInset||{},content=tg.contentSafeAreaInset||{};
   for(const edge of ['top','bottom','left','right']){
    const device=Math.max(0,Number(system[edge])||0),overlay=Math.max(0,Number(content[edge])||0);
    document.documentElement.style.setProperty(`--safe-${edge}`,`calc(max(env(safe-area-inset-${edge}, 0px), ${device}px) + ${overlay}px)`);
   }
  };
  updateSafe();
  if(tg.isVersionAtLeast?.('8.0')){
   tg.onEvent('safeAreaChanged',updateSafe);
   tg.onEvent('contentSafeAreaChanged',updateSafe);
   tg.onEvent('fullscreenChanged',updateSafe);
   // Older/unsupported clients keep the expanded view; a failed request must not interrupt startup.
   if(!tg.isFullscreen&&typeof tg.requestFullscreen==='function'){
    try{tg.requestFullscreen();}catch{}
   }
  }
  if(state)applyTheme();
 }catch{}
}
try{const loaded=isDemo?demoState():await loadState();state=loaded||emptyState();validateState(state);state.settings.theme='light';initializeWorkspace(state);render();initTelegram();if(!globalThis.Telegram?.WebApp)window.addEventListener('load',initTelegram,{once:true});if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});if(!isDemo){if(state.settings.onboardingVersion!==4)welcome();else if(state.settings.backupNoticeSeen!==true)backupNotice();}}catch(err){storageReadOnly=true;state=emptyState();render();info('Ошибка загрузки','Данные не изменены. Перезагрузи приложение или восстанови копию в настройках.','Причина: '+esc(err.message));}

// Progressive forms retain the original controls and values while hiding later
// fields. Native validation runs only for the current step, then for all fields.
function progressiveForm(form,titles,groups){
 const nodes=[...form.children].filter(n=>!n.matches('.form-error,.sheet-footer'));
 const pages=groups.map(indices=>{const section=document.createElement('section');section.className='form-page';for(const i of indices)if(nodes[i])section.append(nodes[i]);form.insertBefore(section,form.querySelector('.form-error'));return section;});
 const heading=document.createElement('p');heading.className='form-step-label';form.prepend(heading);
 const footer=form.querySelector('.sheet-footer'),submit=footer.querySelector('[type=submit]'),label=submit.textContent;
 const back=document.createElement('button');back.type='button';back.className='button secondary';back.textContent='Назад';footer.prepend(back);
 const originallyDisabled=new Set([...form.elements].filter(e=>e.disabled));let step=0;
 const draw=()=>{pages.forEach((page,i)=>{page.hidden=i!==step;for(const field of page.querySelectorAll('input,select,textarea'))field.disabled=i!==step||originallyDisabled.has(field);});heading.textContent=`${step+1} из ${pages.length} · ${titles[step]}`;back.hidden=step===0;submit.textContent=step===pages.length-1?label:'Далее';form.querySelector('.form-error').textContent='';sheet.scrollTop=0;};
 back.onclick=()=>{step--;draw();};
 form.addEventListener('submit',e=>{if(step<pages.length-1){e.preventDefault();e.stopImmediatePropagation();step++;draw();}else{for(const page of pages)for(const field of page.querySelectorAll('input,select,textarea'))field.disabled=originallyDisabled.has(field);}},true);
 draw();
}

// Zero is a placeholder until the user edits; blur restores it if left empty.
document.addEventListener('focusin',e=>{const el=e.target;if(el.matches('input[type=number]:not([readonly])')&&Number(el.value)===0&&el.value!==''){el.dataset.emptyZero='1';el.value='';el.placeholder||='0';}});
document.addEventListener('focusout',e=>{const el=e.target;if(el.matches('input[type=number]')&&el.dataset.emptyZero){if(el.value==='')el.value='0';delete el.dataset.emptyZero;}},true);
let touchOrigin=null;
document.addEventListener('touchstart',e=>{const focused=document.activeElement;touchOrigin=focused?.matches('input:not([type=range]):not([type=checkbox]),textarea')&&!e.target.closest('input,textarea,select')?{y:e.touches[0]?.clientY,focused}:null;},{passive:true});
document.addEventListener('touchmove',e=>{if(touchOrigin&&Math.abs(e.touches[0].clientY-touchOrigin.y)>14){touchOrigin.focused.blur();touchOrigin=null;}},{passive:true});
document.addEventListener('touchend',()=>{touchOrigin=null;},{passive:true});

function detailPages(key,titles,markers){
 const body=sheet.querySelector('.sheet-body'),nodes=[...body.children];
 const nav=document.createElement('div');nav.className='segmented detail-tabs';nav.setAttribute('aria-label','Разделы площадки');
 const pages=titles.map(()=>{const section=document.createElement('section');section.className='detail-page';return section;});
 let page=0;
 for(const node of nodes){if(node.matches('.detail-title,.report-toolbar')){const match=markers.find(([text])=>node.textContent.startsWith(text));if(match)page=match[1];}pages[page].append(node);}
 const select=index=>{detailPage[key]=index;pages.forEach((el,i)=>{el.hidden=i!==index;});[...nav.children].forEach((button,i)=>{button.classList.toggle('active',i===index);button.setAttribute('aria-pressed',String(i===index));});sheet.scrollTop=0;};
 titles.forEach((title,i)=>{const button=document.createElement('button');button.type='button';button.textContent=title;button.onclick=()=>select(i);nav.append(button);});
 body.append(nav,...pages);select(detailPage[key]||0);
}

