function welcome(step=0){
 step=Math.max(0,Math.min(2,Number(step)||0));
 const titles=['Привет, я Кей!','Всё на твоём устройстве','Давай попробуем?'];
 const content=[`<div class="intro-feature">${icon('box',22)}<div><strong>Мерч</strong><p>Запасы, фото и себестоимость.</p></div></div><div class="intro-feature">${icon('calc',22)}<div><strong>Расчёт</strong><p>Цены, акции и окупаемость.</p></div></div><div class="intro-feature">${icon('calendar',22)}<div><strong>Площадки</strong><p>Маркеты, полки и продажи.</p></div></div>`,
 `<p class="intro-copy">Запасы и расчёты — только на устройстве. На наш сервер не отправляются.</p><div class="intro-tip">${icon('download',22)}<span>Сохраняй резервную копию в настройках.</span></div><p class="intro-copy intro-future">Друзья и совместный учёт — в планах.</p>`,
 `<p class="intro-copy">В демо есть готовый мерч и расчёт. Попробуй выбрать товары и изменить цены.</p><div class="intro-tip">${icon('lock',22)}<span>Твои запасы останутся отдельно. Изменения в демо не сохраняются.</span></div>`][step];
 const controls=step===2?`<div class="intro-demo-actions"><button class="button" data-action="welcome-demo">${isDemo?'Продолжить демо':'Зайти в демо'}</button><button class="button secondary" data-action="welcome-done">Разберусь сам</button></div>`:`<button class="button secondary intro-arrow" data-action="welcome-step" data-value="0" aria-label="Предыдущий слайд" ${step===0?'disabled':''}>${icon('back',22)}</button><button class="button ${step===0?'intro-arrow':''}" data-action="welcome-step" data-value="${step+1}" aria-label="${step===0?'Следующий слайд':'Хорошо, далее'}">${step===0?icon('arrow',22):'Хорошо'}</button>`;
 setSheet('«Твой Мерч»',`<div class="intro-scene">${art(['kei-neutral','kei-explain','kei-folded'][step],'intro-character')}<section class="intro-panel" aria-labelledby="intro-title"><span class="dialogue-name">Кей</span><h3 id="intro-title" tabindex="-1">${titles[step]}</h3>${content}</section></div><div class="intro-navigation"><span class="intro-progress" aria-label="Страница ${step+1} из 3">${[0,1,2].map(i=>`<i class="${i===step?'current':''}"></i>`).join('')}</span><div class="intro-buttons">${controls}</div></div>`);
 sheet.classList.add('welcome-sheet');
 sheet.querySelector('#intro-title').focus({preventScroll:true});
}
async function finishWelcome(){
 await commit(next=>{next.settings.onboardingSeen=true;next.settings.onboardingVersion=4;next.settings.backupNoticeSeen=true;});
 closeSheet();navigate('inventory');
}
function boundedStorage(operation){
 let timer;
 return Promise.race([operation,new Promise((_,reject)=>{timer=setTimeout(()=>reject(new Error('Хранилище не ответило. Попробуй ещё раз — твои данные не изменены.')),6000);})]).finally(()=>clearTimeout(timer));
}
async function switchDemo(enabled){
 if(busy||enabled===isDemo)return;
 if(storageReadOnly)throw new Error('Сначала восстанови доступ к данным в настройках.');
 busy=true;
 try{
  clearTimeout(saveTimer);
  let next;
  if(enabled){
   await boundedStorage(saveState(state));
   personalSnapshot=clone(state);
   next=demoState();
  }else{
   next=personalSnapshot?clone(personalSnapshot):(await boundedStorage(loadState()))||emptyState();
  }
  validateState(next);initializeWorkspace(next);next.settings.theme=state.settings.theme;
  // Commit the mode only after loading succeeds; never persist demo data.
  closeSheet();
  for(const pending of photoCache.values())pending.then(url=>{if(url)URL.revokeObjectURL(url);});
  photoCache.clear();demoPhotos.clear();
  state=next;isDemo=enabled;personalSnapshot=enabled?personalSnapshot:null;
  search='';categoryFilter='';inventorySort='name';detailPage={};calcOpen=false;placesTab='markets';eventFilter='all';
  settingsReturn={view:'inventory',scroll:0};
  // Preserve Telegram launch parameters and hash, changing only the demo flag.
  try{const url=new URL(location.href);if(enabled)url.searchParams.set('demo','1');else url.searchParams.delete('demo');window.history.replaceState(null,'',url.href);}catch{}
  navigate('inventory');toast(enabled?'Демо открыто. Можно пробовать всё.':'Ты вышел из демо');
 }finally{busy=false;}
}

