function finishEventPrompt(id){
 const event=state.events.find(e=>e.id===id);if(!event||event.status==='completed')return;
 const recorded=soldCounts(event),leftovers=Object.fromEntries(event.plan.lines.map(l=>[l.itemId,l.qty-(recorded[l.itemId]||0)]));
 const choose=()=>{
  const form=openForm('1 из 2 · Что осталось?',`<p class="sheet-description">Укажи непроданный мерч. Уже внесённые продажи учтены.</p><div class="stock-grid">${event.plan.lines.map(l=>stockCard({...l,id:l.itemId},leftovers[l.itemId],l.qty-(recorded[l.itemId]||0),`name="left-${esc(l.itemId)}" required`,'по учёту')).join('')}</div>`,'Далее',async f=>{
   for(const l of event.plan.lines)leftovers[l.itemId]=formNum(f,'left-'+l.itemId);
   review();
  });
 };
 const review=()=>{
  const counts=remainingSales(event,leftovers),units=Object.values(counts).reduce((n,q)=>n+q,0),recordedRevenue=event.sales.reduce((n,s)=>n+s.revenue,0),estimate=event.plan.lines.reduce((n,l)=>n+counts[l.itemId]*l.price,0);
  const form=openForm('2 из 2 · Завершение',`<p class="sheet-description">Ещё не записано: ${units} проданных шт.</p>${event.plan.lines.filter(l=>counts[l.itemId]>0).map(l=>`<div class="detail-row"><span>${esc(l.name)}</span><strong>${counts[l.itemId]} шт.</strong></div>`).join('')}${units?field('Выручка за эти продажи, ₽','revenue',estimate,'number','required min="0" max="1000000000" step="0.01"','Учти скидки и наборы.'):'<p>Все продажи уже внесены.</p>'}<p class="sheet-description">Ранее записано ${money(recordedRevenue)}. Остатки вернутся в свободный запас.</p>`,'Завершить маркет',async f=>{
   await commit(next=>finishEventByRemaining(next,id,leftovers,units?formNum(f,'revenue'):null),'Маркет завершён');eventDetail(id);
  });
  const back=document.createElement('button');back.type='button';back.className='button secondary';back.textContent='Назад';back.onclick=choose;form.querySelector('.sheet-footer').prepend(back);
 };choose();
}
function syncChoice(tile){
 const input=tile.querySelector('input[type=number]'),qty=Number(input.value)||0,max=Number(input.max);tile.classList.toggle('selected',qty>0);
 tile.querySelector('[data-counter="-1"]').disabled=qty<=0;tile.querySelector('[data-counter="1"]').disabled=qty>=max;
 const picture=tile.querySelector('[data-counter-toggle]');picture.setAttribute('aria-pressed',String(qty>0));picture.setAttribute('aria-label',`${qty?'Убрать':'Выбрать'} ${tile.querySelector('h3').textContent}`);
}
function updateStockSelection(){
 for(const tile of document.querySelectorAll('#app .stock-choice'))syncChoice(tile);
 for(const button of document.querySelectorAll('[data-calc-next],.wizard-nav [data-action="calc-step"], [data-action="save-event"],.bundle-create'))button.disabled=!state.draft.lines.length&&button.dataset.value!=='0';
 const promos=document.querySelector('#calc-promos');if(promos){promos.outerHTML=promoSection(projection(state.draft));hydratePhotos();}
 const prices=document.querySelector('#pro-prices .plan-lines');if(prices){prices.innerHTML=projection(state.draft).lines.map(l=>planLine(l,'pro')).join('');prepareInputs(prices);hydratePhotos();}
}
document.addEventListener('click',e=>{
 const counter=e.target.closest('[data-counter],[data-counter-toggle]');if(!counter||counter.disabled||busy||storageReadOnly)return;
 const tile=counter.closest('.stock-choice'),input=tile.querySelector('input[type=number]'),current=Number(input.value)||0;
 input.value=String(counter.hasAttribute('data-counter-toggle')?(current?0:1):Math.min(Number(input.max),Math.max(0,current+Number(counter.dataset.counter))));
 input.dispatchEvent(new Event('input',{bubbles:true}));input.dispatchEvent(new Event('change',{bubbles:true}));syncChoice(tile);
});
document.addEventListener('input',e=>{const tile=e.target.closest('.stock-choice');if(tile)syncChoice(tile);});

