function quantityPicker(id){
 const item=state.inventory.find(i=>i.id===id);if(!item)return;
 const max=freeStock(id,state.editingId),qty=state.draft.lines.find(l=>l.itemId===id)?.qty||0;
 const form=openForm(esc(item.name),`<p class="sheet-description">Беру на маркет · доступно ${max} шт.</p><div class="quantity-picker"><button type="button" data-step="-10" aria-label="Уменьшить на 10">−10</button><button type="button" data-step="-1" aria-label="Уменьшить на 1">−1</button><input name="qty" aria-label="Количество на маркет" type="number" inputmode="numeric" value="${qty}" required min="0" max="${max}" step="1"><button type="button" data-step="1" aria-label="Увеличить на 1">+1</button><button type="button" data-step="10" aria-label="Увеличить на 10">+10</button></div>`,'Готово',async f=>{await commit(next=>setPlanQuantity(next,id,formNum(f,'qty')));closeSheet();});
 const refresh=()=>{const value=Number(form.elements.qty.value)||0;for(const b of form.querySelectorAll('[data-step]'))b.disabled=Number(b.dataset.step)<0?value<=0:value>=max;};
 form.addEventListener('click',e=>{const button=e.target.closest('[data-step]');if(!button)return;form.elements.qty.value=Math.max(0,Math.min(max,(Number(form.elements.qty.value)||0)+Number(button.dataset.step)));refresh();});
 form.elements.qty.addEventListener('input',refresh);refresh();
}
function updateEditingViewport(){
 const el=document.activeElement,editing=!!el?.matches('input:not([readonly]):not([type=range]):not([type=checkbox]):not([type=file]),textarea,select');
 document.documentElement.classList.toggle('editing-field',editing);
 const vv=window.visualViewport;
 document.documentElement.style.setProperty('--visible-height',`${vv?.height||window.innerHeight}px`);
 document.documentElement.style.setProperty('--keyboard-offset',`${Math.max(0,window.innerHeight-(vv?.height||window.innerHeight)-(vv?.offsetTop||0))}px`);
}
function revealFocusedField(){
 updateEditingViewport();const el=document.activeElement;
 if(!el?.matches('input:not([readonly]):not([type=range]):not([type=checkbox]),textarea,select'))return;
 const vv=window.visualViewport,rect=el.getBoundingClientRect(),top=vv?.offsetTop||0,bottom=top+(vv?.height||innerHeight);
 if(rect.bottom>bottom-24||rect.top<top+24)el.scrollIntoView({block:'center',behavior:'instant'});
}
document.addEventListener('focusin',()=>{updateEditingViewport();setTimeout(revealFocusedField,250);});
document.addEventListener('focusout',()=>setTimeout(updateEditingViewport,0));
window.visualViewport?.addEventListener('resize',revealFocusedField);
window.addEventListener('resize',updateEditingViewport);
document.addEventListener('keydown',e=>{if(e.target.matches('[data-action="quantity-picker"]')&&['Enter',' '].includes(e.key)){e.preventDefault();quantityPicker(e.target.dataset.id);}});
